      } else if (typeof table[key] !== 'object' || table[key] === null || Array.isArray(table[key])) {
        const fullPath = this.currentTablePath.concat(keyPath.slice(0, i + 1))
        throw new ParseError(this.lineNumber + 1, `${this.pathToString(fullPath)} is not a table`)
      }

      table = table[key]
    }

    const lastKey = keyPath[keyPath.length - 1]

    if (lastKey in table) {
      const fullPath = this.currentTablePath.concat(keyPath)
      throw new ParseError(this.lineNumber + 1, `key ${this.pathToString(fullPath)} is defined twice`)
    }

    table[lastKey] = value
  }

  parseValue(text) {
    text = text.trim()

    if (text === '') {
      throw new ParseError(this.lineNumber + 1, 'expected a value')
    }

    // Boolean
    if (text === 'true') return true
    if (text === 'false') return false

    // String
    if (text.startsWith('"')) {
      return this.parseBasicString(text)
    }
    if (text.startsWith("'")) {
      return this.parseLiteralString(text)
    }

    // Array
    if (text.startsWith('[')) {
      return this.parseArray(text)
    }

    // Inline table
    if (text.startsWith('{')) {
      return this.parseInlineTable(text)
    }

    // Number
    const numberResult = this.parseNumber(text)
    if (numberResult !== null) {
      return numberResult
    }

    // Invalid value
    // Extract just the first word for the error message
    const words = text.split(/[\s\[\]{}=,]/)[0]
    throw new ParseError(this.lineNumber + 1, `invalid value ${words}`)
  }

  parseBasicString(text) {
    if (!text.endsWith('"')) {
      throw new ParseError(this.lineNumber + 1, 'unterminated string')
    }

    // Check for trailing text after the string
    const afterQuote = text.slice(text.lastIndexOf('"') + 1)
    if (!this.isBlankAfterComments(afterQuote)) {
      throw new ParseError(this.lineNumber + 1, 'trailing text after a value')
    }

    // Find the closing quote
    let endQuoteIndex = -1
    for (let i = text.length - 1; i >= 1; i--) {
      if (text[i] === '"' && text[i - 1] !== '\\') {
        endQuoteIndex = i
        break
      }
    }

    if (endQuoteIndex === -1) {
      throw new ParseError(this.lineNumber + 1, 'unterminated string')
    }

    const content = text.slice(1, endQuoteIndex)
    return this.decodeBasicString('"' + content + '"')
  }

  parseLiteralString(text) {
    if (!text.endsWith("'")) {
      throw new ParseError(this.lineNumber + 1, 'unterminated string')
    }

    // Check for trailing text after the string
    const afterQuote = text.slice(text.lastIndexOf("'") + 1)
    if (!this.isBlankAfterComments(afterQuote)) {
      throw new ParseError(this.lineNumber + 1, 'trailing text after a value')
    }

    // Find the closing quote
    let endQuoteIndex = -1
    for (let i = text.length - 1; i >= 1; i--) {
      if (text[i] === "'") {
        endQuoteIndex = i
        break
      }
    }

    if (endQuoteIndex === -1) {
      throw new ParseError(this.lineNumber + 1, 'unterminated string')
    }

    const content = text.slice(1, endQuoteIndex)
    return this.decodeLiteralString("'" + content + "'")
  }

  parseArray(text) {
    if (!text.endsWith(']')) {
      throw new ParseError(this.lineNumber + 1, 'unterminated array')
    }

    // Check for trailing text
    const afterBracket = text.slice(text.lastIndexOf(']') + 1).trim()
    if (afterBracket !== '' && !afterBracket.startsWith('#') && !afterBracket.startsWith(';')) {
      throw new ParseError(this.lineNumber + 1, 'trailing text after a value')
    }

    const content = text.slice(1, -1).trim()
    const array = []

    if (content === '') {
      return array
    }

    const items = this.splitArrayItems(content)
    for (const item of items) {
      array.push(this.parseValue(item))
    }

    return array
  }

  splitArrayItems(content) {
    const items = []
    let current = ''
    let depth = 0
    let inString = false
    let stringChar = null

    for (let i = 0; i < content.length; i++) {
      const char = content[i]

      if (!inString && (char === '"' || char === "'")) {
        inString = true
        stringChar = char
        current += char
      } else if (inString && char === stringChar && content[i - 1] !== '\\') {
        inString = false
        stringChar = null
        current += char
      } else if (!inString && (char === '[' || char === '{')) {
        depth++
        current += char
      } else if (!inString && (char === ']' || char === '}')) {
        depth--
        current += char
      } else if (!inString && char === ',' && depth === 0) {
        items.push(current.trim())
        current = ''
      } else {
        current += char
      }
    }

    if (current.trim() !== '') {
      items.push(current.trim())
    }

    return items
  }

  parseInlineTable(text) {
    if (!text.endsWith('}')) {
      throw new ParseError(this.lineNumber + 1, 'unterminated inline table')
    }

    // Check for trailing text
    const afterBrace = text.slice(text.lastIndexOf('}') + 1).trim()
    if (afterBrace !== '' && !afterBrace.startsWith('#') && !afterBrace.startsWith(';')) {
      throw new ParseError(this.lineNumber + 1, 'trailing text after a value')
    }

    const content = text.slice(1, -1).trim()
    const table = {}

    if (content === '') {
      return table
    }

    const pairs = this.splitInlineTablePairs(content)
    for (const pair of pairs) {
      const eqIndex = pair.indexOf('=')
      if (eqIndex === -1) {
        throw new ParseError(this.lineNumber + 1, 'expected = in an inline table')
      }

      const keyPart = pair.slice(0, eqIndex).trim()
      const valuePart = pair.slice(eqIndex + 1).trim()

      const keyPath = this.parseDottedName(keyPart)
      const value = this.parseValue(valuePart)

      let current = table
      for (let i = 0; i < keyPath.length - 1; i++) {
        const key = keyPath[i]
        if (!(key in current)) {
          current[key] = {}
        }
        current = current[key]
      }

      const lastKey = keyPath[keyPath.length - 1]
      if (lastKey in current) {
        throw new ParseError(this.lineNumber + 1, `key ${lastKey} is defined twice`)
      }
      current[lastKey] = value
    }

    return table
  }

  splitInlineTablePairs(content) {
    const pairs = []
    let current = ''
    let depth = 0
    let inString = false
    let stringChar = null

    for (let i = 0; i < content.length; i++) {
      const char = content[i]

      if (!inString && (char === '"' || char === "'")) {
        inString = true
        stringChar = char
        current += char
      } else if (inString && char === stringChar && content[i - 1] !== '\\') {
        inString = false
        stringChar = null
        current += char
      } else if (!inString && (char === '[' || char === '{')) {
        depth++
        current += char
      } else if (!inString && (char === ']' || char === '}')) {
        depth--
        current += char
      } else if (!inString && char === ',' && depth === 0) {
        pairs.push(current.trim())
        current = ''
      } else {
        current += char
      }
    }

    if (current.trim() !== '') {
      pairs.push(current.trim())
    }

    return pairs
  }

  parseNumber(text) {
    // Try to parse as integer
    const intMatch = text.match(/^([+-]?\d{1,}(?:_\d+)*)$/)
    if (intMatch) {
      const numStr = intMatch[1].replace(/_/g, '')
      return parseInt(numStr, 10)
    }

    // Try to parse as float
    const floatMatch = text.match(/^([+-]?(?:\d+(?:_\d+)*)?\.(\d+(?:_\d+)*)(?:[eE][+-]?\d+(?:_\d+)*)? | [+-]?\d+(?:_\d+)*[eE][+-]?\d+(?:_\d+)*)$/)

    // Actually let me do this more carefully
    let pointer = 0

    // Optional sign
    if (text[pointer] === '+' || text[pointer] === '-') {
      pointer++
    }

    // Check for number
    let hasDigitsBefore = false
    while (pointer < text.length && (text[pointer].match(/\d/) || text[pointer] === '_')) {
      if (text[pointer].match(/\d/)) {
        hasDigitsBefore = true
      }
      pointer++
    }

    let isFloat = false

    // Check for decimal point
    if (text[pointer] === '.') {
      isFloat = true
      pointer++
      let hasDigitsAfter = false
      while (pointer < text.length && (text[pointer].match(/\d/) || text[pointer] === '_')) {
        if (text[pointer].match(/\d/)) {
          hasDigitsAfter = true
        }
        pointer++
      }
      if (!hasDigitsAfter && !hasDigitsBefore) {
        return null
      }
    }

    // Check for exponent
    if (pointer < text.length && (text[pointer] === 'e' || text[pointer] === 'E')) {
      isFloat = true
      pointer++
      if (text[pointer] === '+' || text[pointer] === '-') {
        pointer++
      }
      let hasExpDigits = false
      while (pointer < text.length && (text[pointer].match(/\d/) || text[pointer] === '_')) {
        if (text[pointer].match(/\d/)) {
          hasExpDigits = true
        }
        pointer++
      }
      if (!hasExpDigits) {
        return null
      }
    }

    // Check if we consumed the whole string
    if (pointer !== text.length) {
      return null
    }

    if (!hasDigitsBefore && !isFloat) {
      return null
    }

    const numStr = text.replace(/_/g, '')
    if (isFloat) {
      return parseFloat(numStr)
    } else {
      return parseInt(numStr, 10)
    }
  }
