{"file_path":"src/formatter.js","content":"/**
 * The two renderings of a parsed document: canonical JSON, and one line per
 * node holding its path and its type.
 */

function compareKeys(a, b) {
  const x = Array.from(a)
  const y = Array.from(b)
  const n = Math.min(x.length, y.length)
  for (let i = 0; i < n; i++) {
    const p = x[i].codePointAt(0)
    const q = y[i].codePointAt(0)
    if (p !== q) return p < q ? -1 : 1
  }
  if (x.length === y.length) return 0
  return x.length < y.length ? -1 : 1
}

function sortedKeys(table) {
  return Array.from(table.map.keys()).sort(compareKeys)
}

function render(node, depth) {
  const pad = '  '.repeat(depth)
  const inner = '  '.repeat(depth + 1)
  if (node.kind === 'table') {
    const keys = sortedKeys(node)
    if (keys.length === 0) return '{}'
    const parts = keys.map(
      (key) => `${inner}${JSON.stringify(key)}: ${render(node.map.get(key), depth + 1)}`
    )
    return `{\n${parts.join(',\n')}\n${pad}}`
  }
  if (node.kind === 'array') {
    if (node.items.length === 0) return '[]'
    const parts = node.items.map((item) => `${inner}${render(item, depth + 1)}`)
    return `[\n${parts.join(',\n')}\n${pad}]`
  }
  if (node.kind === 'string') return JSON.stringify(node.value)
  if (node.kind === 'boolean') return node.value ? 'true' : 'false'
  return JSON.stringify(node.value)
}

export function formatJSON(root) {
  return `${render(root, 0)}\n`
}

function emit(node, path, lines) {
  lines.push(`${path} ${node.kind}`)
  walk(node, path, lines)
}

function walk(node, path, lines) {
  if (node.kind === 'table') {
    for (const key of sortedKeys(node)) {
      emit(node.map.get(key), path ? `${path}.${key}` : key, lines)
    }
  } else if (node.kind === 'array') {
    node.items.forEach((item, index) => {
      emit(item, `${path}[${index}]`, lines)
    })
  }
}

export function formatKeys(root) {
  const lines = []
  walk(root, '', lines)
  return lines.map((line) => `${line}\n`).join('')
}
