/**
 * TOML Parser
 * 
 * Parses TOML format according to the specification.
 */

export class ParseError extends Error {
  constructor(lineNumber, reason) {
    super(`error: line ${lineNumber}: ${reason}`)
    this.lineNumber = lineNumber
    this.reason = reason
  }
}

export class TOMLParser {
  constructor(input) {
    this.input = input
    this.lines = input.split('\n')
    // Drop the empty tail a trailing newline leaves
    if (this.lines.length > 0 && this.lines[this.lines.length - 1] === '') {
      this.lines.pop()
    }
    this.lineNumber = 0
    this.root = {}
    this.currentTable = this.root
    this.currentTablePath = []
  }

  parse() {
    for (this.lineNumber = 0; this.lineNumber < this.lines.length; this.lineNumber++) {
      const line = this.lines[this.lineNumber]
      this.parseLine(line)
    }
    return this.root
  }

  parseLine(line) {
    // Remove comments (but not inside strings)
    line = this.stripComments(line)

    // Skip blank lines
    if (this.isBlankLine(line)) {
      return
    }

    const trimmed = line.trimStart()

    // Skip comment lines
    if (trimmed.startsWith('#') || trimmed.startsWith(';')) {
      return
    }

    // Check if it's a header
    if (trimmed.startsWith('[')) {
      this.parseHeader(trimmed)
      return
    }

    // Otherwise it's a key-value assignment
    this.parseKeyValue(line)
  }

  stripComments(line) {
    let inSingleQuote = false
    let inDoubleQuote = false
    let result = ''
    let lastCharWasWhitespace = true // Start of line counts as having whitespace before

    for (let i = 0; i < line.length; i++) {
      const char = line[i]
      const isWhitespace = char === ' ' || char === '\t'

      if (char === "'" && !inDoubleQuote && (i === 0 || line[i - 1] !== '\\')) {
        inSingleQuote = !inSingleQuote
        result += char
        lastCharWasWhitespace = false
      } else if (char === '"' && !inSingleQuote && (i === 0 || line[i - 1] !== '\\')) {
        inDoubleQuote = !inDoubleQuote
        result += char
        lastCharWasWhitespace = false
      } else if ((char === '#' || char === ';') && !inSingleQuote && !inDoubleQuote && lastCharWasWhitespace) {
        // Found comment start (has whitespace before it or is at line start)
        break
      } else {
        result += char
        lastCharWasWhitespace = isWhitespace
      }
    }

    return result
  }

  isBlankLine(line) {
    return /^\s*$/.test(line)
  }

  parseHeader(line) {
    let isArrayOfTables = false

    if (line.startsWith('[[')) {
      isArrayOfTables = true
      line = line.slice(2)
    } else {
      line = line.slice(1)
    }

    // Find closing bracket
    let closingIndex = -1
    let inQuote = false
    let quoteChar = null
    for (let i = 0; i < line.length; i++) {
      if ((line[i] === '"' || line[i] === "'") && (i === 0 || line[i - 1] !== '\\')) {
        if (!inQuote) {
          inQuote = true
          quoteChar = line[i]
        } else if (line[i] === quoteChar) {
          inQuote = false
          quoteChar = null
        }
      } else if (!inQuote && (isArrayOfTables ? line[i] === ']' && line[i + 1] === ']' : line[i] === ']')) {
        closingIndex = i
        break
      }
    }

    if (closingIndex === -1) {
      throw new ParseError(this.lineNumber + 1, 'unterminated table header')
    }

    const headerContent = line.slice(0, closingIndex)
    const afterHeader = line.slice(closingIndex + (isArrayOfTables ? 2 : 1))

    // Check for trailing text
    if (!this.isBlankAfterComments(afterHeader)) {
      throw new ParseError(this.lineNumber + 1, 'trailing text after a table header')
    }

    // Parse the dotted name
    const path = this.parseDottedName(headerContent)

    if (isArrayOfTables) {
      this.setCurrentTableAsArrayElement(path)
    } else {
      this.setCurrentTable(path)
    }
  }

  isBlankAfterComments(text) {
    const stripped = text.trimStart()
    if (stripped === '') return true
    if (stripped.startsWith('#') || stripped.startsWith(';')) return true
    return false
  }

  parseDottedName(text) {
    const names = []
    let current = ''
    let inQuote = false
    let quoteChar = null
    let i = 0

    while (i < text.length) {
      const char = text[i]

      if (!inQuote && (char === '"' || char === "'")) {
        inQuote = true
        quoteChar = char
        i++
        continue
      }

      if (inQuote && char === quoteChar && (i === 0 || text[i - 1] !== '\\')) {
        inQuote = false
        quoteChar = null
        i++
        continue
      }

      if (inQuote) {
        current += char
        i++
        continue
      }

      if (char === '.') {
        if (current.trim() === '') {
          throw new ParseError(this.lineNumber + 1, 'expected a name')
        }
        names.push(this.decodeName(current.trim()))
        current = ''
        i++
        continue
      }

      if (char === ' ' || char === '\t') {
        if (current !== '') {
          // Look ahead to see if it's a dot or end
          const nextNonWhitespace = this.findNextNonWhitespace(text, i)
          if (nextNonWhitespace === '.' || nextNonWhitespace === null || nextNonWhitespace === '') {
            names.push(this.decodeName(current.trim()))
            current = ''
          }
        }
        i++
        continue
      }

      current += char
      i++
    }

    if (inQuote) {
      throw new ParseError(this.lineNumber + 1, 'unterminated string')
    }

    if (current.trim() !== '') {
      names.push(this.decodeName(current.trim()))
    }

    if (names.length === 0) {
      throw new ParseError(this.lineNumber + 1, 'expected a name')
    }

    return names
  }

  findNextNonWhitespace(text, startIndex) {
    for (let i = startIndex; i < text.length; i++) {
      if (text[i] !== ' ' && text[i] !== '\t') {
        return text[i]
      }
    }
    return null
  }

  decodeName(name) {
    if (name.startsWith('"') && name.endsWith('"')) {
      return this.decodeBasicString(name)
    }
    if (name.startsWith("'") && name.endsWith("'")) {
      return this.decodeLiteralString(name)
    }
    return name
  }

  decodeBasicString(str) {
    // Remove quotes
    str = str.slice(1, -1)
    let result = ''
    let i = 0

    while (i < str.length) {
      if (str[i] === '\\' && i + 1 < str.length) {
        const next = str[i + 1]
        switch (next) {
          case '"': result += '"'; i += 2; break
          case '\\': result += '\\'; i += 2; break
          case 'n': result += '\n'; i += 2; break
          case 't': result += '\t'; i += 2; break
          case 'r': result += '\r'; i += 2; break
          case '0': result += '\0'; i += 2; break
          case 'u':
            if (i + 5 < str.length) {
              const hex = str.slice(i + 2, i + 6)
              if (/^[0-9a-fA-F]{4}$/.test(hex)) {
                result += String.fromCharCode(parseInt(hex, 16))
                i += 6
              } else {
                throw new ParseError(this.lineNumber + 1, `invalid escape \\${next}`)
              }
            } else {
              throw new ParseError(this.lineNumber + 1, `invalid escape \\${next}`)
            }
            break
          default:
            throw new ParseError(this.lineNumber + 1, `invalid escape \\${next}`)
        }
      } else if (str[i] === '\\') {
        throw new ParseError(this.lineNumber + 1, 'unterminated string')
      } else {
        result += str[i]
        i++
      }
    }

    return result
  }

  decodeLiteralString(str) {
    // Remove quotes and keep everything as-is
    return str.slice(1, -1)
  }

  setCurrentTable(path) {
    let table = this.root

    for (let i = 0; i < path.length; i++) {
      const key = path[i]

      if (!(key in table)) {
        table[key] = {}
      } else if (typeof table[key] !== 'object' || table[key] === null || Array.isArray(table[key])) {
        throw new ParseError(this.lineNumber + 1, `${this.pathToString(path.slice(0, i + 1))} is not a table`)
      }

      table = table[key]
    }

    // Check if this exact table was already set as current by a header
    const fullPath = this.pathToString(path)
    if (this.isHeaderAlreadyDeclared(path)) {
      throw new ParseError(this.lineNumber + 1, `table ${fullPath} is defined twice`)
    }

    this.currentTable = table
    this.currentTablePath = path
    this.markTableAsHeaderDeclared(path)
  }

  setCurrentTableAsArrayElement(path) {
    let table = this.root

    for (let i = 0; i < path.length - 1; i++) {
      const key = path[i]

      if (!(key in table)) {
        table[key] = {}
      } else if (typeof table[key] !== 'object' || table[key] === null) {
        throw new ParseError(this.lineNumber + 1, `${this.pathToString(path.slice(0, i + 1))} is not a table`)
      }

      table = table[key]
    }

    const lastKey = path[path.length - 1]

    if (!(lastKey in table)) {
      table[lastKey] = []
    } else if (!Array.isArray(table[lastKey])) {
      throw new ParseError(this.lineNumber + 1, `${this.pathToString(path)} is not an array of tables`)
    }

    const newTable = {}
    table[lastKey].push(newTable)

    this.currentTable = newTable
    this.currentTablePath = path
  }

  isHeaderAlreadyDeclared(path) {
    // Check if this exact path was declared as a header before
    // (not just created implicitly)
    // We need to track this separately
    if (!this.declaredHeaders) {
      this.declaredHeaders = new Set()
    }
    return this.declaredHeaders.has(this.pathToString(path))
  }

  markTableAsHeaderDeclared(path) {
    if (!this.declaredHeaders) {
      this.declaredHeaders = new Set()
    }
    this.declaredHeaders.add(this.pathToString(path))
  }

  pathToString(path) {
    return path.join('.')
  }

  parseKeyValue(line) {
    // Find the = sign
    let equalIndex = -1
    let inQuote = false
    let quoteChar = null

    for (let i = 0; i < line.length; i++) {
      if ((line[i] === '"' || line[i] === "'") && (i === 0 || line[i - 1] !== '\\')) {
        if (!inQuote) {
          inQuote = true
          quoteChar = line[i]
        } else if (line[i] === quoteChar) {
          inQuote = false
          quoteChar = null
        }
      } else if (!inQuote && line[i] === '=') {
        equalIndex = i
        break
      }
    }

    if (equalIndex === -1) {
      throw new ParseError(this.lineNumber + 1, 'expected key = value')
    }

    const keyPart = line.slice(0, equalIndex)
    const valuePart = line.slice(equalIndex + 1)

    // Parse the dotted name key
    const keyPath = this.parseDottedName(keyPart)

    // Parse the value
    const value = this.parseValue(valuePart)

    // Set the value in the current table
    this.setKeyValue(keyPath, value)
  }

  setKeyValue(keyPath, value) {
    let table = this.currentTable

    // Walk through all but the last key, creating tables as needed
    for (let i = 0; i < keyPath.length - 1; i++) {
      const key = keyPath[i]

      if (!(key in table)) {
        table[key] = {}
      } else if (typeof table[key] !== 'object' || table[key] === null || Array.isArray(table[key])) {
        const fullPath = this.currentTablePath.concat(keyPath.slice(0, i + 1))
        throw new ParseError(this.lineNumber + 1, `${this.pathToString(fullPath)} is not a table`)
      }

      table = table[key]
    }

    const lastKey = keyPath[keyPath.length - 1]

    if (lastKey in table) {
      const fullPath = this.currentTablePath.concat(keyPath)
      throw new ParseError(this.lineNumber + 1, `key ${this.pathToString(fullPath)} is defined twice`)
    }

    table[lastKey] = value
  }

  parseValue(text) {
    text = text.trim()

    if (text === '') {
      throw new ParseError(this.lineNumber + 1, 'expected a value')
    }

    // Boolean
    if (text === 'true') return true
    if (text === 'false') return false

    // String
    if (text.startsWith('"')) {
      return this.parseBasicString(text)
    }
    if (text.startsWith("'")) {
      return this.parseLiteralString(text)
    }

    // Array
    if (text.startsWith('[')) {
      return this.parseArray(text)
    }

    // Inline table
    if (text.startsWith('{')) {
      return this.parseInlineTable(text)
    }

    // Number
    const numberResult = this.parseNumber(text)
    if (numberResult !== null) {
      return numberResult
    }

    // Invalid value
    // Extract just the first word for the error message
    const words = text.split(/[\s\[\]{}=,]/)[0]
    throw new ParseError(this.lineNumber + 1, `invalid value ${words}`)
  }

  parseBasicString(text) {
    if (!text.endsWith('"')) {
      throw new ParseError(this.lineNumber + 1, 'unterminated string')
    }

    // Check for trailing text after the string
    const afterQuote = text.slice(text.lastIndexOf('"') + 1)
    if (!this.isBlankAfterComments(afterQuote)) {
      throw new ParseError(this.lineNumber + 1, 'trailing text after a value')
    }

    // Find the closing quote
    let endQuoteIndex = -1
    for (let i = text.length - 1; i >= 1; i--) {
      if (text[i] === '"' && text[i - 1] !== '\\') {
        endQuoteIndex = i
        break
      }
    }

    if (endQuoteIndex === -1) {
      throw new ParseError(this.lineNumber + 1, 'unterminated string')
    }

    const content = text.slice(1, endQuoteIndex)
    return this.decodeBasicString('"' + content + '"')
  }

  parseLiteralString(text) {
    if (!text.endsWith("'")) {
      throw new ParseError(this.lineNumber + 1, 'unterminated string')
    }

    // Check for trailing text after the string
    const afterQuote = text.slice(text.lastIndexOf("'") + 1)
    if (!this.isBlankAfterComments(afterQuote)) {
      throw new ParseError(this.lineNumber + 1, 'trailing text after a value')
    }

    // Find the closing quote
    let endQuoteIndex = -1
    for (let i = text.length - 1; i >= 1; i--) {
      if (text[i] === "'") {
        endQuoteIndex = i
        break
      }
    }

    if (endQuoteIndex === -1) {
      throw new ParseError(this.lineNumber + 1, 'unterminated string')
    }

    const content = text.slice(1, endQuoteIndex)
    return this.decodeLiteralString("'" + content + "'")
  }

  parseArray(text) {
    if (!text.endsWith(']')) {
      throw new ParseError(this.lineNumber + 1, 'unterminated array')
    }

    // Check for trailing text
    const afterBracket = text.slice(text.lastIndexOf(']') + 1).trim()
    if (afterBracket !== '' && !afterBracket.startsWith('#') && !afterBracket.startsWith(';')) {
      throw new ParseError(this.lineNumber + 1, 'trailing text after a value')
    }

    const content = text.slice(1, -1).trim()
    const array = []

    if (content === '') {
      return array
    }

    const items = this.splitArrayItems(content)
    for (const item of items) {
      array.push(this.parseValue(item))
    }

    return array
  }

  splitArrayItems(content) {
    const items = []
    let current = ''
    let depth = 0
    let inString = false
    let stringChar = null

    for (let i = 0; i < content.length; i++) {
      const char = content[i]

      if (!inString && (char === '"' || char === "'")) {
        inString = true
        stringChar = char
        current += char
      } else if (inString && char === stringChar && content[i - 1] !== '\\') {
        inString = false
        stringChar = null
        current += char
      } else if (!inString && (char === '[' || char === '{')) {
        depth++
        current += char
      } else if (!inString && (char === ']' || char === '}')) {
        depth--
        current += char
      } else if (!inString && char === ',' && depth === 0) {
        items.push(current.trim())
        current = ''
      } else {
        current += char
      }
    }

    if (current.trim() !== '') {
      items.push(current.trim())
    }

    return items
  }

  parseInlineTable(text) {
    if (!text.endsWith('}')) {
      throw new ParseError(this.lineNumber + 1, 'unterminated inline table')
    }

    // Check for trailing text
    const afterBrace = text.slice(text.lastIndexOf('}') + 1).trim()
    if (afterBrace !== '' && !afterBrace.startsWith('#') && !afterBrace.startsWith(';')) {
      throw new ParseError(this.lineNumber + 1, 'trailing text after a value')
    }

    const content = text.slice(1, -1).trim()
    const table = {}

    if (content === '') {
      return table
    }

    const pairs = this.splitInlineTablePairs(content)
    for (const pair of pairs) {
      const eqIndex = pair.indexOf('=')
      if (eqIndex === -1) {
        throw new ParseError(this.lineNumber + 1, 'expected = in an inline table')
      }

      const keyPart = pair.slice(0, eqIndex).trim()
      const valuePart = pair.slice(eqIndex + 1).trim()

      const keyPath = this.parseDottedName(keyPart)
      const value = this.parseValue(valuePart)

      let current = table
      for (let i = 0; i < keyPath.length - 1; i++) {
        const key = keyPath[i]
        if (!(key in current)) {
          current[key] = {}
        }
        current = current[key]
      }

      const lastKey = keyPath[keyPath.length - 1]
      if (lastKey in current) {
        throw new ParseError(this.lineNumber + 1, `key ${lastKey} is defined twice`)
      }
      current[lastKey] = value
    }

    return table
  }

  splitInlineTablePairs(content) {
    const pairs = []
    let current = ''
    let depth = 0
    let inString = false
    let stringChar = null

    for (let i = 0; i < content.length; i++) {
      const char = content[i]

      if (!inString && (char === '"' || char === "'")) {
        inString = true
        stringChar = char
        current += char
      } else if (inString && char === stringChar && content[i - 1] !== '\\') {
        inString = false
        stringChar = null
        current += char
      } else if (!inString && (char === '[' || char === '{')) {
        depth++
        current += char
      } else if (!inString && (char === ']' || char === '}')) {
        depth--
        current += char
      } else if (!inString && char === ',' && depth === 0) {
        pairs.push(current.trim())
        current = ''
      } else {
        current += char
      }
    }

    if (current.trim() !== '') {
      pairs.push(current.trim())
    }

    return pairs
  }

  parseNumber(text) {
    // Try to parse as integer
    const intMatch = text.match(/^([+-]?\d{1,}(?:_\d+)*)$/)
    if (intMatch) {
      const numStr = intMatch[1].replace(/_/g, '')
      return parseInt(numStr, 10)
    }

    // Try to parse as float
    const floatMatch = text.match(/^([+-]?(?:\d+(?:_\d+)*)?\.(\d+(?:_\d+)*)(?:[eE][+-]?\d+(?:_\d+)*)? | [+-]?\d+(?:_\d+)*[eE][+-]?\d+(?:_\d+)*)$/)

    // Actually let me do this more carefully
    let pointer = 0

    // Optional sign
    if (text[pointer] === '+' || text[pointer] === '-') {
      pointer++
    }

    // Check for number
    let hasDigitsBefore = false
    while (pointer < text.length && (text[pointer].match(/\d/) || text[pointer] === '_')) {
      if (text[pointer].match(/\d/)) {
        hasDigitsBefore = true
      }
      pointer++
    }

    let isFloat = false

    // Check for decimal point
    if (text[pointer] === '.') {
      isFloat = true
      pointer++
      let hasDigitsAfter = false
      while (pointer < text.length && (text[pointer].match(/\d/) || text[pointer] === '_')) {
        if (text[pointer].match(/\d/)) {
          hasDigitsAfter = true
        }
        pointer++
      }
      if (!hasDigitsAfter && !hasDigitsBefore) {
        return null
      }
    }

    // Check for exponent
    if (pointer < text.length && (text[pointer] === 'e' || text[pointer] === 'E')) {
      isFloat = true
      pointer++
      if (text[pointer] === '+' || text[pointer] === '-') {
        pointer++
      }
      let hasExpDigits = false
      while (pointer < text.length && (text[pointer].match(/\d/) || text[pointer] === '_')) {
        if (text[pointer].match(/\d/)) {
          hasExpDigits = true
        }
        pointer++
      }
      if (!hasExpDigits) {
        return null
      }
    }

    // Check if we consumed the whole string
    if (pointer !== text.length) {
      return null
    }

    if (!hasDigitsBefore && !isFloat) {
      return null
    }

    const numStr = text.replace(/_/g, '')
    if (isFloat) {
      return parseFloat(numStr)
    } else {
      return parseInt(numStr, 10)
    }
  }
}

