/**
 * The configuration document parser. It turns the lines of a document into a
 * tree of typed nodes, or throws a ParseError naming the line and the reason.
 */

export class ParseError extends Error {
  constructor(line, reason) {
    super(`line ${line}: ${reason}`)
    this.line = line
    this.reason = reason
  }
}

export function newTable() {
  return { kind: 'table', map: new Map(), explicit: false }
}

function newArray(tableArray) {
  return { kind: 'array', items: [], tableArray: !!tableArray }
}

const BARE = /[A-Za-z0-9_-]/

function isWs(c) {
  return c === ' ' || c === '\t'
}

function isComment(c) {
  return c === '#' || c === ';'
}

function skipWs(s, i) {
  while (i < s.length && isWs(s[i])) i++
  return i
}

function joinPath(prefix, names) {
  const tail = names.join('.')
  return prefix ? `${prefix}.${tail}` : tail
}

const INT_RE = /^[+-]?[0-9]+(?:_[0-9]+)*$/
const FLOAT_RE = /^[+-]?[0-9]+(?:_[0-9]+)*(?:\.[0-9]+(?:_[0-9]+)*)?(?:[eE][+-]?[0-9]+(?:_[0-9]+)*)?$/

function classify(token) {
  if (token === 'true') return { kind: 'boolean', value: true }
  if (token === 'false') return { kind: 'boolean', value: false }
  if (INT_RE.test(token)) {
    return { kind: 'integer', value: Number(token.replace(/_/g, '')) }
  }
  if (FLOAT_RE.test(token) && /[.eE]/.test(token)) {
    return { kind: 'float', value: Number(token.replace(/_/g, '')) }
  }
  return null
}

class Parser {
  constructor(text) {
    const lines = text.split('\n')
    if (lines.length > 0 && lines[lines.length - 1] === '') lines.pop()
    this.lines = lines
    this.root = newTable()
    this.root.explicit = true
    this.cur = this.root
    this.curPath = []
    this.s = ''
    this.lineNo = 0
  }

  err(reason) {
    throw new ParseError(this.lineNo, reason)
  }

  parse() {
    for (let k = 0; k < this.lines.length; k++) {
      this.lineNo = k + 1
      this.parseLine(this.lines[k])
    }
    return this.root
  }

  parseLine(line) {
    this.s = line
    const s = line
    let i = skipWs(s, 0)
    if (i >= s.length) return
    if (isComment(s[i])) return
    if (s[i] === '[') {
      this.parseHeader(i)
      return
    }
    const name = this.parseDottedName(i)
    i = skipWs(s, name.i)
    if (i >= s.length || s[i] !== '=') this.err('expected key = value')
    const prefix = this.curPath.join('.')
    const value = this.parseValue(i + 1, joinPath(prefix, name.names))
    i = skipWs(s, value.i)
    if (i < s.length && !isComment(s[i])) this.err('trailing text after a value')
    this.assign(name.names, value.node)
  }

  /* ---------------------------------------------------------------- headers */

  parseHeader(start) {
    const s = this.s
    let i = start
    let double = false
    if (s[i + 1] === '[') {
      double = true
      i += 2
    } else {
      i += 1
    }
    const name = this.parseDottedName(i)
    i = skipWs(s, name.i)
    if (double) {
      if (s[i] !== ']' || s[i + 1] !== ']') this.err('unterminated table header')
      i += 2
    } else {
      if (s[i] !== ']') this.err('unterminated table header')
      i += 1
    }
    i = skipWs(s, i)
    if (i < s.length && !isComment(s[i])) this.err('trailing text after a table header')
    if (double) this.applyArrayHeader(name.names)
    else this.applyTableHeader(name.names)
  }

  applyTableHeader(names) {
    let table = this.root
    for (let k = 0; k < names.length; k++) {
      const name = names[k]
      const last = k === names.length - 1
      const path = names.slice(0, k + 1).join('.')
      let child = table.map.get(name)
      if (child === undefined) {
        child = newTable()
        table.map.set(name, child)
      } else if (!last && child.kind === 'array' && child.tableArray) {
        child = child.items[child.items.length - 1]
      } else if (child.kind !== 'table') {
        this.err(`${path} is not a table`)
      }
      if (last) {
        if (child.explicit) this.err(`table ${path} is defined twice`)
        child.explicit = true
      }
      table = child
    }
    this.cur = table
    this.curPath = names
  }

  applyArrayHeader(names) {
    let table = this.root
    for (let k = 0; k < names.length - 1; k++) {
      const name = names[k]
      const path = names.slice(0, k + 1).join('.')
      let child = table.map.get(name)
      if (child === undefined) {
        child = newTable()
        table.map.set(name, child)
      } else if (child.kind === 'array' && child.tableArray) {
        child = child.items[child.items.length - 1]
      } else if (child.kind !== 'table') {
        this.err(`${path} is not a table`)
      }
      table = child
    }
    const name = names[names.length - 1]
    const path = names.join('.')
    let array = table.map.get(name)
    if (array === undefined) {
      array = newArray(true)
      table.map.set(name, array)
    } else if (array.kind !== 'array' || !array.tableArray) {
      this.err(`${path} is not an array of tables`)
    }
    const fresh = newTable()
    array.items.push(fresh)
    this.cur = fresh
    this.curPath = names
  }

  /* ------------------------------------------------------------ assignment */

  assign(names, node) {
    this.insert(this.cur, names, node, this.curPath.join('.'))
  }

  insert(root, names, node, prefix) {
    let table = root
    for (let k = 0; k < names.length - 1; k++) {
      const name = names[k]
      const path = joinPath(prefix, names.slice(0, k + 1))
      let child = table.map.get(name)
      if (child === undefined) {
        child = newTable()
        table.map.set(name, child)
      } else if (child.kind === 'array' && child.tableArray) {
        child = child.items[child.items.length - 1]
      } else if (child.kind !== 'table') {
        this.err(`${path} is not a table`)
      }
      table = child
    }
    const name = names[names.length - 1]
    if (table.map.has(name)) {
      this.err(`key ${joinPath(prefix, names)} is defined twice`)
    }
    table.map.set(name, node)
  }

  /* ------------------------------------------------------------------ names */

  parseDottedName(start) {
    const s = this.s
    let i = start
    const names = []
    for (;;) {
      i = skipWs(s, i)
      if (i >= s.length) this.err('expected a name')
      const c = s[i]
      if (c === '"') {
        const r = this.readBasicString(i)
        names.push(r.value)
        i = r.i
      } else if (c === "'") {
        const r = this.readLiteralString(i)
        names.push(r.value)
        i = r.i
      } else {
        let j = i
        while (j < s.length && BARE.test(s[j])) j++
        if (j === i) this.err('expected a name')
        names.push(s.slice(i, j))
        i = j
      }
      const k = skipWs(s, i)
      if (k < s.length && s[k] === '.') {
        i = k + 1
        continue
      }
      i = k
      break
    }
    return { names, i }
  }

  /* ---------------------------------------------------------------- strings */

  readBasicString(start) {
    const s = this.s
    let i = start + 1
    let out = ''
    for (;;) {
      if (i >= s.length) this.err('unterminated string')
      const c = s[i]
      if (c === '"') {
        i++
        break
      }
      if (c === '\\') {
        const e = s[i + 1]
        if (e === undefined) this.err('unterminated string')
        if (e === '"') { out += '"'; i += 2 }
        else if (e === '\\') { out += '\\'; i += 2 }
        else if (e === 'n') { out += '\n'; i += 2 }
        else if (e === 't') { out += '\t'; i += 2 }
        else if (e === 'r') { out += '\r'; i += 2 }
        else if (e === '0') { out += '\0'; i += 2 }
        else if (e === 'u') {
          const hex = s.slice(i + 2, i + 6)
          if (!/^[0-9a-fA-F]{4}$/.test(hex)) this.err('invalid escape \\u')
          out += String.fromCharCode(parseInt(hex, 16))
          i += 6
        } else {
          this.err(`invalid escape \\${e}`)
        }
        continue
      }
      out += c
      i++
    }
    return { value: out, i }
  }

  readLiteralString(start) {
    const s = this.s
    const end = s.indexOf("'", start + 1)
    if (end === -1) this.err('unterminated string')
    return { value: s.slice(start + 1, end), i: end + 1 }
  }

  /* ----------------------------------------------------------------- values */

  parseValue(start, path) {
    const s = this.s
    let i = skipWs(s, start)
    if (i >= s.length) this.err('expected a value')
    const c = s[i]
    if (c === ',' || c === ']' || c === '}' || isComment(c)) this.err('expected a value')
    if (c === '"') {
      const r = this.readBasicString(i)
      return { node: { kind: 'string', value: r.value }, i: r.i }
    }
    if (c === "'") {
      const r = this.readLiteralString(i)
      return { node: { kind: 'string', value: r.value }, i: r.i }
    }
    if (c === '[') return this.parseArray(i, path)
    if (c === '{') return this.parseInlineTable(i, path)
    let j = i
    while (j < s.length && !isWs(s[j]) && s[j] !== ',' && s[j] !== ']' && s[j] !== '}') j++
    const token = s.slice(i, j)
    const node = classify(token)
    if (node === null) this.err(`invalid value ${token}`)
    return { node, i: j }
  }

  parseArray(start, path) {
    const s = this.s
    let i = start + 1
    const array = newArray(false)
    for (;;) {
      i = skipWs(s, i)
      if (i >= s.length || isComment(s[i])) this.err('unterminated array')
      if (s[i] === ']') {
        i++
        break
      }
      const value = this.parseValue(i, `${path}[${array.items.length}]`)
      array.items.push(value.node)
      i = skipWs(s, value.i)
      if (i >= s.length || isComment(s[i])) this.err('unterminated array')
      if (s[i] === ',') {
        i++
        continue
      }
      if (s[i] === ']') {
        i++
        break
      }
      this.err('unterminated array')
    }
    return { node: array, i }
  }

  parseInlineTable(start, path) {
    const s = this.s
    let i = start + 1
    const table = newTable()
    i = skipWs(s, i)
    if (i < s.length && s[i] === '}') return { node: table, i: i + 1 }
    for (;;) {
      i = skipWs(s, i)
      if (i >= s.length || isComment(s[i])) this.err('unterminated inline table')
      const name = this.parseDottedName(i)
      i = skipWs(s, name.i)
      if (i >= s.length || s[i] !== '=') this.err('expected = in an inline table')
      const value = this.parseValue(i + 1, joinPath(path, name.names))
      this.insert(table, name.names, value.node, path)
      i = skipWs(s, value.i)
      if (i >= s.length || isComment(s[i])) this.err('unterminated inline table')
      if (s[i] === ',') {
        i++
        continue
      }
      if (s[i] === '}') {
        i++
        break
      }
      this.err('unterminated inline table')
    }
    return { node: table, i }
  }
}

export function parseDocument(text) {
  return new Parser(text).parse()
}

