/**
 * Output Formatter
 * 
 * Formats parsed TOML as JSON or keys output
 */

export function formatAsJSON(obj) {
  const sorted = sortKeys(obj)
  return JSON.stringify(sorted, null, 2) + '\n'
}

function sortKeys(obj) {
  if (obj === null || typeof obj !== 'object') {
    return obj
  }

  if (Array.isArray(obj)) {
    return obj.map(item => sortKeys(item))
  }

  const sorted = {}
  const keys = Object.keys(obj).sort()

  for (const key of keys) {
    sorted[key] = sortKeys(obj[key])
  }

  return sorted
}

export function formatAsKeys(obj) {
  const lines = []
  walkKeys(obj, '', lines)
  return lines.join('\n') + (lines.length > 0 ? '\n' : '')
}

function walkKeys(obj, path, lines, depth = 0) {
  if (typeof obj !== 'object' || obj === null) {
    return
  }

  if (Array.isArray(obj)) {
    // Array of tables
    for (let i = 0; i < obj.length; i++) {
      const item = obj[i]
      const itemPath = path ? `${path}[${i}]` : `[${i}]`
      walkKeys(item, itemPath, lines, depth + 1)
    }
  } else {
    // Regular object
    const keys = Object.keys(obj).sort()

    for (const key of keys) {
      const value = obj[key]
      const newPath = path ? `${path}.${key}` : key

      if (typeof value === 'object' && value !== null) {
        if (Array.isArray(value)) {
          // Check if it's an array of tables
          if (value.length > 0 && typeof value[0] === 'object' && value[0] !== null && !Array.isArray(value[0])) {
            lines.push(`${newPath} array`)
            walkKeys(value, newPath, lines, depth + 1)
          } else {
            // Regular array (not array of tables)
            const type = getArrayType(value)
            lines.push(`${newPath} ${type}`)
          }
        } else {
          // Regular object/table
          lines.push(`${newPath} table`)
          walkKeys(value, newPath, lines, depth + 1)
        }
      } else {
        // Scalar value
        const type = getType(value)
        lines.push(`${newPath} ${type}`)
      }
    }
  }
}

function getType(value) {
  if (typeof value === 'boolean') {
    return 'boolean'
  }
  if (typeof value === 'string') {
    return 'string'
  }
  if (typeof value === 'number') {
    if (Number.isInteger(value)) {
      return 'integer'
    } else {
      return 'float'
    }
  }
  return 'unknown'
}

function getArrayType(arr) {
  if (arr.length === 0) {
    return 'array'
  }

  // Check if all elements are the same type
  const firstType = typeof arr[0]

  if (arr.every(item => typeof item === firstType)) {
    if (firstType === 'boolean') {
      return 'array'
    }
    if (firstType === 'string') {
      return 'array'
    }
    if (firstType === 'number') {
      return 'array'
    }
    if (firstType === 'object' && arr[0] !== null) {
      if (Array.isArray(arr[0])) {
        return 'array'
      }
      if (arr.every(item => !Array.isArray(item))) {
        return 'array'
      }
    }
  }

  return 'array'
}

