import { TOMLParser, ParseError } from './parser.js'
import { formatAsJSON, formatAsKeys } from './formatter.js'

async function main() {
  const args = process.argv.slice(2)

  if (args.length !== 1 || (args[0] !== 'json' && args[0] !== 'keys')) {
    process.stderr.write('error: usage: cli.js json|keys\n')
    process.exit(2)
  }

  const mode = args[0]

  try {
    // Read all input from stdin
    const input = await readStdin()

    // Parse the TOML
    const parser = new TOMLParser(input)
    const result = parser.parse()

    // Format and output
    if (mode === 'json') {
      process.stdout.write(formatAsJSON(result))
    } else {
      process.stdout.write(formatAsKeys(result))
    }

    process.exit(0)
  } catch (err) {
    if (err instanceof ParseError) {
      process.stderr.write(`${err.message}\n`)
    } else {
      process.stderr.write(`error: ${err.message}\n`)
    }
    process.exit(2)
  }
