import { parseDocument, ParseError } from './parser.js'
import { formatJSON, formatKeys } from './formatter.js'

function readStdin() {
  return new Promise((resolve, reject) => {
    let data = ''
    process.stdin.setEncoding('utf8')
    process.stdin.on('data', (chunk) => {
      data += chunk
    })
    process.stdin.on('end', () => resolve(data))
    process.stdin.on('error', reject)
  })
}

function fail(message) {
  process.stderr.write(`error: ${message}\n`)
  process.exit(2)
}

async function main() {
  const args = process.argv.slice(2)
  if (args.length !== 1 || (args[0] !== 'json' && args[0] !== 'keys')) {
    fail('usage: cli.js json|keys')
    return
  }
  const input = await readStdin()
  let output
  try {
    const root = parseDocument(input)
    output = args[0] === 'json' ? formatJSON(root) : formatKeys(root)
  } catch (error) {
    if (error instanceof ParseError) {
      fail(error.message)
      return
    }
    throw error
  }
  process.stdout.write(output)
}

main()

